// rr_arbiter: round-robin arbiter for N requesters (default 4).
// Implements microarchitecture.md: one priority pointer, a wrapping
// priority search, pointer moves one past the winner on a grant.
`default_nettype none

module rr_arbiter #(
  parameter integer N = 4
) (
  input  wire         clk,
  input  wire         rst_n,
  input  wire [N-1:0] req,
  output reg  [N-1:0] grant
);

  localparam integer W     = (N > 1) ? $clog2(N) : 1;
  localparam integer LASTI = N - 1;
  localparam [W-1:0] LAST  = LASTI[W-1:0];
  localparam [W-1:0] ZERO  = {W{1'b0}};
  localparam integer ONEI  = 1;
  localparam [W-1:0] ONE   = ONEI[W-1:0];

  reg  [W-1:0] ptr;
  reg  [W-1:0] winner;
  reg  [W-1:0] idx;
  reg          found;
  integer      k;

  // Wrapping priority search from ptr; every output defaulted first.
  always @(*) begin
    grant  = {N{1'b0}};
    winner = ptr;
    found  = 1'b0;
    idx    = ptr;
    for (k = 0; k < N; k = k + 1) begin
      if (!found && req[idx]) begin
        found      = 1'b1;
        winner     = idx;
        grant[idx] = 1'b1;
      end
      if (idx == LAST) begin
        idx = ZERO;
      end else begin
        idx = idx + ONE;
      end
    end
  end

  wire [W-1:0] ptr_next = (winner == LAST) ? ZERO : (winner + ONE);

  // Pointer register: synchronous active-low reset to 0; moves only on a grant.
  always @(posedge clk) begin
    if (!rst_n) begin
      ptr <= ZERO;
    end else if (found) begin
      ptr <= ptr_next;
    end
  end

`ifdef FORMAL
  // Design-intent properties (interface_spec.md section 6).
  reg f_past_valid;
  initial f_past_valid = 1'b0;
  always @(posedge clk) f_past_valid <= 1'b1;

  always @(*) begin
    if (!f_past_valid) assume (!rst_n);
  end

  always @(*) begin
    if (f_past_valid) begin
      assert (ptr <= LAST);
      assert ((grant & (grant - 1'b1)) == {N{1'b0}});
      assert ((grant & ~req) == {N{1'b0}});
      assert ((|req) == (|grant));
    end
  end

  always @(posedge clk) begin
    if (f_past_valid) begin
      if (!$past(rst_n))
        assert (ptr == ZERO);
      else if (|$past(req))
        assert (ptr == (($past(winner) == LAST) ? ZERO : ($past(winner) + ONE)));
      else
        assert (ptr == $past(ptr));
      cover ($past(rst_n) && ($past(ptr) == LAST) && (ptr == ZERO));
    end
  end

  always @(*) begin
    if (f_past_valid) cover (rst_n && (&req));
  end

  genvar gi, gk;
  generate
    for (gi = 0; gi < N; gi = gi + 1) begin : g_fv
      localparam [W+1:0] IW = gi;
      localparam [W+1:0] NW = N;
      wire [W+1:0] pw = {2'b00, ptr};
      wire [W+1:0] dist_i = (pw <= IW) ? (IW - pw) : (IW + NW - pw);
      reg  [W+1:0] wcnt;
      always @(posedge clk) begin
        if (!rst_n) wcnt <= {(W+2){1'b0}};
        else if (req[gi] && !grant[gi]) wcnt <= wcnt + 1'b1;
        else wcnt <= {(W+2){1'b0}};
      end
      always @(*) begin
        if (f_past_valid) begin
          assert (wcnt <= (NW - 1'b1));
          assert ((wcnt + dist_i) <= (NW - 1'b1));
          cover (rst_n && grant[gi]);
          cover (wcnt == (NW - 1'b1));
        end
      end
      for (gk = 0; gk < N; gk = gk + 1) begin : g_ord
        if (gk != gi) begin : g_ne
          localparam [W+1:0] KW = gk;
          wire [W+1:0] dist_k = (pw <= KW) ? (KW - pw) : (KW + NW - pw);
          always @(*) begin
            if (f_past_valid && grant[gi] && (dist_k < dist_i)) assert (!req[gk]);
          end
        end
      end
    end
  endgenerate
`endif

endmodule

`default_nettype wire
=== END FILE ===
