// Self-checking testbench for rr_arbiter at N=4 and N=5 side by side.
`timescale 1ns/1ps
`default_nettype none

module rr_arbiter_tb;
  reg        clk;
  reg        rst_n;
  reg  [3:0] req4;
  reg  [4:0] req5;
  wire [3:0] grant4;
  wire [4:0] grant5;

  rr_arbiter #(.N(4)) u_arb4 (.clk(clk), .rst_n(rst_n), .req(req4), .grant(grant4));
  rr_arbiter #(.N(5)) u_arb5 (.clk(clk), .rst_n(rst_n), .req(req5), .grant(grant5));

  initial clk = 1'b0;
  always #5 clk = ~clk;

  integer passed;
  integer failed;
  integer p4, p5, np4, np5;
  integer w4 [0:3];
  integer w5 [0:4];
  integer seed;
  integer c;
  integer b;
  reg [31:0] rv;
  reg [3:0] prq4;
  reg [4:0] prq5;
  reg [3:0] cov_alone4;
  reg [4:0] cov_alone5;
  reg cov_none4, cov_none5, cov_all4, cov_all5;
  reg cov_maxw4, cov_maxw5, cov_held4, cov_held5, cov_rst4, cov_rst5;
  reg rot_on;
  integer rot_i;
  reg [8*64-1:0] nonce;

  // Reference model: first requester at or after p, wrapping at n.
  function [7:0] fgrant(input [7:0] r, input integer p, input integer n);
    integer kk;
    integer ix;
    reg done;
    begin
      fgrant = 8'd0;
      done = 1'b0;
      for (kk = 0; kk < n; kk = kk + 1) begin
        ix = (p + kk) % n;
        if (!done && r[ix]) begin
          fgrant[ix] = 1'b1;
          done = 1'b1;
        end
      end
    end
  endfunction

  // Reference pointer update: one past the winner, or hold with no request.
  function integer fnext(input [7:0] r, input integer p, input integer n);
    integer kk;
    integer ix;
    reg done;
    begin
      fnext = p;
      done = 1'b0;
      for (kk = 0; kk < n; kk = kk + 1) begin
        ix = (p + kk) % n;
        if (!done && r[ix]) begin
          fnext = (ix + 1) % n;
          done = 1'b1;
        end
      end
    end
  endfunction

  task check_cycle;
    reg [7:0] e4;
    reg [7:0] e5;
    reg ok;
    begin
      e4 = fgrant({4'b0000, req4}, p4, 4);
      e5 = fgrant({3'b000, req5}, p5, 5);
      if (grant4 === e4[3:0]) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("N4 grant %b expected %b (req %b, model ptr %0d)", grant4, e4[3:0], req4, p4);
      end
      if (grant5 === e5[4:0]) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("N5 grant %b expected %b (req %b, model ptr %0d)", grant5, e5[4:0], req5, p5);
      end
      if (rot_on) begin
        if (grant4 === (4'b0001 << (rot_i % 4))) passed = passed + 1;
        else begin
          failed = failed + 1;
          $error("N4 rotation step %0d: grant %b", rot_i, grant4);
        end
        if (grant5 === (5'b00001 << (rot_i % 5))) passed = passed + 1;
        else begin
          failed = failed + 1;
          $error("N5 rotation step %0d: grant %b", rot_i, grant5);
        end
      end
      // Fairness: cycles waited with request held, never more than N-1.
      ok = 1'b1;
      for (b = 0; b < 4; b = b + 1) begin
        if (rst_n && req4[b] && !grant4[b]) w4[b] = w4[b] + 1;
        else w4[b] = 0;
        if (w4[b] > 3) begin
          ok = 1'b0;
          failed = failed + 1;
          $error("N4 requester %0d waited %0d cycles", b, w4[b]);
        end
        if (w4[b] == 3) cov_maxw4 = 1'b1;
        if (rst_n && req4[b] && prq4[b] && (((req4 ^ prq4) & ~(4'b0001 << b)) != 4'b0000))
          cov_held4 = 1'b1;
      end
      for (b = 0; b < 5; b = b + 1) begin
        if (rst_n && req5[b] && !grant5[b]) w5[b] = w5[b] + 1;
        else w5[b] = 0;
        if (w5[b] > 4) begin
          ok = 1'b0;
          failed = failed + 1;
          $error("N5 requester %0d waited %0d cycles", b, w5[b]);
        end
        if (w5[b] == 4) cov_maxw5 = 1'b1;
        if (rst_n && req5[b] && prq5[b] && (((req5 ^ prq5) & ~(5'b00001 << b)) != 5'b00000))
          cov_held5 = 1'b1;
      end
      if (ok) passed = passed + 1;
      // Coverage
      if (rst_n && (req4 == 4'b0000) && (grant4 == 4'b0000)) cov_none4 = 1'b1;
      if (rst_n && (req5 == 5'b00000) && (grant5 == 5'b00000)) cov_none5 = 1'b1;
      if (rst_n && (req4 != 4'b0000) && ((req4 & (req4 - 4'd1)) == 4'b0000) && (grant4 == req4))
        cov_alone4 = cov_alone4 | req4;
      if (rst_n && (req5 != 5'b00000) && ((req5 & (req5 - 5'd1)) == 5'b00000) && (grant5 == req5))
        cov_alone5 = cov_alone5 | req5;
      if (rst_n && (req4 == 4'b1111)) cov_all4 = 1'b1;
      if (rst_n && (req5 == 5'b11111)) cov_all5 = 1'b1;
      if (!rst_n && (req4 != 4'b0000)) cov_rst4 = 1'b1;
      if (!rst_n && (req5 != 5'b00000)) cov_rst5 = 1'b1;
      prq4 = req4;
      prq5 = req5;
    end
  endtask

  task step(input [3:0] r4, input [4:0] r5, input rn);
    begin
      @(negedge clk);
      req4  = r4;
      req5  = r5;
      rst_n = rn;
      #1;
      check_cycle;
      if (rn) begin
        np4 = fnext({4'b0000, r4}, p4, 4);
        np5 = fnext({3'b000, r5}, p5, 5);
      end else begin
        np4 = 0;
        np5 = 0;
      end
      @(posedge clk);
      p4 = np4;
      p5 = np5;
    end
  endtask

  task cover_check(input hit, input [8*24-1:0] name);
    begin
      if (hit) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("coverage goal not reached: %0s", name);
      end
    end
  endtask

  initial begin
    passed = 0;
    failed = 0;
    p4 = 0; p5 = 0; np4 = 0; np5 = 0;
    seed = 32'h1c32d8ed;
    for (b = 0; b < 4; b = b + 1) w4[b] = 0;
    for (b = 0; b < 5; b = b + 1) w5[b] = 0;
    rst_n = 1'b0;
    req4 = 4'b0000;
    req5 = 5'b00000;
    prq4 = 4'b0000;
    prq5 = 5'b00000;
    cov_alone4 = 4'b0000; cov_alone5 = 5'b00000;
    cov_none4 = 1'b0; cov_none5 = 1'b0; cov_all4 = 1'b0; cov_all5 = 1'b0;
    cov_maxw4 = 1'b0; cov_maxw5 = 1'b0; cov_held4 = 1'b0; cov_held5 = 1'b0;
    cov_rst4 = 1'b0; cov_rst5 = 1'b0;
    rot_on = 1'b0;
    rot_i = 0;
    nonce = 0;

    // Reset with no requests, then idle (no requests).
    for (c = 0; c < 3; c = c + 1) step(4'b0000, 5'b00000, 1'b0);
    step(4'b0000, 5'b00000, 1'b1);
    step(4'b0000, 5'b00000, 1'b1);

    // Each requester alone, twice round.
    for (c = 0; c < 10; c = c + 1)
      step(((c % 5) < 4) ? (4'b0001 << (c % 5)) : 4'b0000, 5'b00001 << (c % 5), 1'b1);

    // Reset during traffic, then strict rotation with everyone requesting.
    step(4'b1111, 5'b11111, 1'b1);
    step(4'b1111, 5'b11111, 1'b0);
    step(4'b1111, 5'b11111, 1'b0);
    rot_on = 1'b1;
    for (c = 0; c < 20; c = c + 1) begin
      rot_i = c;
      step(4'b1111, 5'b11111, 1'b1);
    end
    rot_on = 1'b0;

    // A held request among changing others.
    for (c = 0; c < 24; c = c + 1) begin
      rv = $random(seed);
      step(rv[3:0] | 4'b0100, rv[8:4] | 5'b01000, 1'b1);
    end

    // Random traffic, sparse and dense, with occasional reset.
    for (c = 0; c < 2000; c = c + 1) begin
      rv = $random(seed);
      step(rv[3:0], rv[8:4], (rv[15:10] != 6'd0));
    end
    for (c = 0; c < 2000; c = c + 1) begin
      rv = $random(seed);
      step(rv[3:0] | rv[19:16], rv[8:4] | rv[24:20], (rv[30:25] != 6'd0));
    end
    step(4'b0000, 5'b00000, 1'b1);

    cover_check(cov_none4, "N4 no requests");
    cover_check(cov_none5, "N5 no requests");
    cover_check(cov_alone4 == 4'b1111, "N4 each alone");
    cover_check(cov_alone5 == 5'b11111, "N5 each alone");
    cover_check(cov_all4, "N4 all requesting");
    cover_check(cov_all5, "N5 all requesting");
    cover_check(cov_held4, "N4 held among changing");
    cover_check(cov_held5, "N5 held among changing");
    cover_check(cov_maxw4, "N4 wait N-1");
    cover_check(cov_maxw5, "N5 wait N-1");
    cover_check(cov_rst4, "N4 reset in traffic");
    cover_check(cov_rst5, "N5 reset in traffic");

    if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end
endmodule

`default_nettype wire
=== END FILE ===
